// Refresh token rotation with reuse detection (defensive shape).
const crypto = require("crypto")

const refreshTokens = new Map() // tokenId -> { hash, userId, used, expiresAt }

function issueRefresh(userId) {
  const raw = crypto.randomBytes(32).toString("hex")
  const id = crypto.randomBytes(8).toString("hex")
  refreshTokens.set(id, {
    hash: crypto.createHash("sha256").update(raw).digest("hex"),
    userId,
    used: false,
    expiresAt: Date.now() + 14 * 24 * 3600 * 1000
  })
  return { id, raw } // raw goes to the client as HttpOnly cookie
}

function rotate(id, raw) {
  const rec = refreshTokens.get(id)
  const hash = crypto.createHash("sha256").update(raw).digest("hex")
  if (!rec || rec.hash !== hash || rec.expiresAt < Date.now()) {
    return { ok: false }
  }
  if (rec.used) {
    // Reuse = theft signal: the legitimate client already rotated.
    for (const [otherId, other] of refreshTokens) {
      if (other.userId === rec.userId) refreshTokens.delete(otherId)
    }
    audit.append({ action: "refresh.reuse", user: rec.userId })
    return { ok: false, revokedAll: true }
  }
  rec.used = true // old token dies now; a fresh one is issued below
  const next = issueRefresh(rec.userId)
  return { ok: true, refresh: next }
}
